 function select(path,label,items,value,expert=false,id='f-'+path.replaceAll('.','-')/* lot 5 (accessibilité) : identifiant propre quand la même liste est aussi dessinée dans un autre outil */){return '<div class="calc-field'+(expert?' b-expert':'')+'"><label for="'+id+'">'+esc(label)+'</label><select data-field="'+path+'" id="'+id+'">'+opts(items,value)+'</select></div>';}
 const lookup=key=>B.asset(state(),key);
