 const SIMS=[['carburant','Combustible (vehículos)',[['distance','Distancia por partida (km)'],['consommation','Consumo (litros cada 100 km)'],['prixUnitaire','Precio del litro ($)']]],['entretien','Mantenimiento (vehículos)',[['parPartie','Coste por partida ($)']]],['reparation','Reparaciones (vehículos)',[['parPartie','Coste por partida ($)']]],['assurance','Seguro (vehículos)',[['parPartie','Coste por partida ($)']]],['munitions','Munición (cada intento de misión)',[['parTentative','Coste por intento ($)']]],['echec','Intentos fallidos (Mis actividades, Mi objetivo, Mi tiempo de juego)',[['tentativesRatees','Intentos fallidos de cada 10']]]];
 function hypothesesBlock(){const an=state().analysis;return '<details class="calc-optional b-hypotheses b-expert" id="calc-hypotheses"><summary>Mis hipótesis: combustible, mantenimiento, munición, intentos fallidos</summary><p class="calc-note"><b>Alcance:</b> estas hipótesis cuentan en los ocho cálculos. El plan de negocio tiene sus propias casillas; solo toma la munición simulada, añadida a los gastos de cada intento de misión. Ninguna de estas mecánicas está confirmada en GTA VI: no se cuenta nada sin que lo elijas, y una cifra elegida sigue marcada como “simulación” en todas partes, incluso en tus cálculos guardados. Si escribes tú mismo el coste por partida de una compra, la simulación no se le suma.</p>'+SIMS.map(([k,label,fields])=>'<fieldset class="b-sim-item"><legend>'+check('analysis.simulations.'+k,label,an.simulations[k])+'</legend><div class="calc-fields" data-sim-fields="'+k+'" '+(an.simulations[k]?'':'hidden')+'>'+fields.map(([f,l])=>field('analysis.sim.'+k+'.'+f,l,an.sim[k][f],{id:'sim-'+k+'-'+f,max:k==='echec'?10:1e12,integer:k==='echec'})).join('')+'</div></fieldset>').join('')+'<p class="calc-note">Combustible: distancia × consumo ÷ 100 × precio del litro = coste por partida.</p></details>';}
