 const FOLD_KEY='lk-calc-folds-v1';let foldState={all:null,items:{}},foldForced=false,foldAnimate=null;
 try{const raw=localStorage.getItem(FOLD_KEY);if(raw){const v=JSON.parse(raw);if(v&&typeof v==='object'){foldState.all=v.all===true?true:v.all===false?false:null;foldState.items=v.items&&typeof v.items==='object'?v.items:{};}}}catch{}
 function foldPersist(){try{localStorage.setItem(FOLD_KEY,JSON.stringify(foldState));}catch{}}
 function foldIsOpen(id,def=false){if(foldForced)return true;if(foldState.all===true)return true;if(foldState.all===false)return false;const v=foldState.items[id];return typeof v==='boolean'?v:def;}
 function foldSet(id,open){foldState.items[id]=open;foldState.all=null;foldPersist();}
 function foldAll(open){foldState={all:open,items:{}};foldPersist();}
 /* fold(id, {n, title, teaser, body, open, kicker, tone}) : body est une chaîne ou une fonction (calculée seulement à l'ouverture). */
 function fold(id,o){const open=foldIsOpen(id,o.open===true);const body=open?(typeof o.body==='function'?o.body():o.body):'';
  return '<section class="b-fold'+(open?' is-open':'')+(o.tone?' b-fold--'+o.tone:'')+'" data-fold="'+esc(id)+'"><h3 class="b-fold-h"><button type="button" class="b-fold-head" data-fold-head="'+esc(id)+'" aria-expanded="'+open+'" aria-controls="fold-'+esc(id)+'"><span class="b-fold-num" aria-hidden="true">'+(o.n!==undefined?esc(String(o.n)):'<i></i>')+'</span><span class="b-fold-text"><span class="b-fold-title">'+esc(o.title)+'</span>'+(o.teaser?'<span class="b-fold-teaser">'+o.teaser+'</span>':'')+'</span><span class="b-fold-chevron" aria-hidden="true"></span></button></h3><div class="b-fold-body" id="fold-'+esc(id)+'"'+(open?'':' hidden')+'>'+body+'</div></section>';}
 /* Les résultats des huit outils : hypothèses, compromis et formules deviennent des points repliables, sans réécrire chaque outil. */
 function foldify(container,tool){if(!container)return;const doc=container.ownerDocument;let k=0;
  container.querySelectorAll('.b-fold').forEach(f=>{const open=foldIsOpen(f.dataset.fold,false);f.classList.toggle('is-open',open);const body=f.querySelector(':scope>.b-fold-body');if(body)body.hidden=!open;f.querySelector('.b-fold-head')?.setAttribute('aria-expanded',String(open));});
  const wrap=(node,id,title,teaser)=>{const sec=doc.createElement('div');sec.innerHTML=fold(id,{title,teaser,body:'',open:false});const f=sec.firstChild,body=f.querySelector('.b-fold-body');node.parentNode.insertBefore(f,node);body.appendChild(node);if(node.tagName==='DETAILS'){node.open=true;node.classList.add('b-fold-inner');}if(!foldIsOpen(id,false))body.hidden=true;else{body.hidden=false;f.classList.add('is-open');f.querySelector('.b-fold-head').setAttribute('aria-expanded','true');}};
  container.querySelectorAll(':scope .b-assumptions-box').forEach(node=>{if(node.closest('.b-fold'))return;if(node.dataset.teaser){wrap(node,tool+'-assumptions','Lo que cuenta en este cálculo',esc(node.dataset.teaser));return;}const items=[...node.querySelectorAll('.b-assumptions li')].slice(0,2).map(li=>(li.querySelector('span')?.textContent||'').replace(/\s+/g,' ').trim()+' '+(li.querySelector('b')?.textContent||'').trim()).join(' · ');const missing=node.querySelector('.b-missing');wrap(node,tool+'-assumptions','Lo que cuenta en este cálculo',esc(missing?'Falta una cifra · '+items:items));});
  container.querySelectorAll(':scope details').forEach(node=>{if(node.closest('.b-fold')||node.classList.contains('c-chart-data')||node.classList.contains('b-inline-activity')||node.classList.contains('calc-optional'))return;const sum=node.querySelector(':scope>summary');if(!sum)return;const title=sum.textContent.replace(/\s+/g,' ').trim();sum.hidden=true;wrap(node,tool+'-d'+(k++),title,node.dataset.teaser||(node.classList.contains('b-tradeoff')?'Compara las dos opciones':''));});}
