 return field('goal.players','¿Cuántos jugadores somos, yo incluido?',s.goal.players,{id:'roi-players',min:1,max:100,integer:true})+'<fieldset class="b-roi-activities"><legend>¿Qué actividades van con esta compra?</legend>'+all.map(x=>{const canonical=item?.activityIds?.includes(x.id)||x.purchaseIds?.includes(item?.id);return '<label class="calc-check"><input type="checkbox" data-b-roi-activity="'+esc(x.id)+'" '+(r.activityIds.includes(x.id)?'checked':'')+'>'+esc(x.name)+' · '+(canonical?'vínculo que conoce el sitio':'lo digo yo')+'</label>';}).join('')+'</fieldset><p class="calc-note">Ese vínculo lo dices tú. Las actividades se hacen una tras otra: pagas los gastos antes y recibes la recompensa después. El precio de la compra sustituye lo que hay que comprar antes de empezar, para no contarlo dos veces.</p>'+inlineActivities('roi',null);
