 function orderPrice(a){return a.owned?'ya es tuyo · ningún gasto previsto':a.price===null?'precio desconocido':a.extras===null||a.fees===null?'gastos por concretar':money(a.price+a.extras+a.fees);}
 function orderItems(){const s=state();if(!s.order.keys.length)return '<p class="calc-empty">Añade tu primera compra. Un precio que falta se queda como desconocido.</p>';return s.order.keys.map((key,index)=>{const a=lookup(key);if(!a)return warning('Compra no encontrada: '+key)+btn('Dejar de comparar','data-b-order-remove="'+esc(key)+'"');const i=s.assets.indexOf(a),item=itemFor(a);return '<article class="b-order-item" data-b-order-key="'+esc(key)+'"><div class="b-order-head">'+media(item)+'<div><strong>'+esc((index+1)+'. '+a.name)+'</strong><p>'+esc(labels[item?.type]||'Compra libre')+' · '+orderPrice(a)+'</p></div></div><div class="b-order-actions">'+btn('↑','data-b-order-up="'+esc(key)+'" aria-label="Subir '+esc(a.name)+'" '+(index===0?'disabled':''))+btn('↓','data-b-order-down="'+esc(key)+'" aria-label="Bajar '+esc(a.name)+'" '+(index===s.order.keys.length-1?'disabled':''))+btn('Editar','data-b-order-edit="'+esc(key)+'" aria-expanded="'+(orderEditor===key)+'"')+btn('Quitar','data-b-order-remove="'+esc(key)+'"')+'</div><div '+(orderEditor===key?'':'hidden')+' class="b-order-editor">'+(!a.itemId?field('assets.'+i+'.name','Nombre de esta compra',a.name,{type:'text'}):'')+priceField(key,'order-price-'+index)+'<div class="b-expert">'+field('assets.'+i+'.extras','Gastos y mejoras ($)',a.extras)+field('assets.'+i+'.fees','Otros gastos iniciales ($)',a.fees)+select('assets.'+i+'.incomeMode','Lo que gano después de esta compra',[['none','Ningún ingreso extra'],['personal','Sí, más o menos esta cifra por hora (la escribo)'],['roi','Resultado vinculado de “¿Vale la pena?”']],a.incomeMode,false,'order-assets-'+i+'-incomeMode')+field('assets.'+i+'.boostHourly','Me hace ganar de más ($ por hora)',a.boostHourly,{hint:'Solo si ese dinero se suma de verdad a lo que ya ganas. El juego no promete nada.'})+'<label class="calc-check"><input type="checkbox" data-b-owned="'+esc(key)+'" '+(a.owned?'checked':'')+'> Ya tengo esta compra (requisito de la actividad cumplido)</label>'+usageField(i,a,'order-usage-'+index)+(s.order.keys.length>1?'<fieldset class="b-requires"><legend>Comprar antes que este (si es obligatorio)</legend>'+s.order.keys.filter(k=>k!==key).map(k=>{const o=lookup(k);return o?'<label class="calc-check"><input type="checkbox" data-b-requires="'+esc(key)+'|'+esc(k)+'" '+((a.requires||[]).includes(k)?'checked':'')+'> '+esc(o.name)+'</label>':'';}).join('')+'<p class="calc-note">Márcalo solo si el juego lo exige de verdad (por ejemplo, una mejora que necesita el vehículo). El orden propuesto lo respetará.</p></fieldset>':'')+'</div></div></article>';}).join('')+(lastRemoved?btn('Deshacer la retirada de la cesta','data-b-order-undo="1"'):'');}
 function decorate(){const s=state();
 $('goal-cycle-fields').insertAdjacentHTML('beforeend','<details class="calc-optional"><summary>Escribir mis misiones aquí</summary>'+inlineActivities('goal')+'</details>');
 $('panel-session').querySelector('.calc-fields').insertAdjacentHTML('beforeend','<div class="b-expert">'+field('session.daysPerWeek','¿Cuántos días por semana juego?',s.session.daysPerWeek,{min:1,max:7,integer:true})+field('session.usualMinutes','Una partida suele durar (minutos)',s.session.usualMinutes,{min:1,max:1440})+'</div>');
 $('f-session-maxRepeat').closest('.calc-field').classList.add('b-expert');$('f-session-maxRepeat').dataset.integer='1';
 // Les activités et la réserve restent modifiables en mode Simple.
 $('panel-session').querySelector('.calc-fields').insertAdjacentHTML('beforeend','<div class="wide"><h4>Mi dinero para esta partida</h4><div class="calc-fields">'+field('goal.capital','Ya tengo ($)',s.goal.capital,{id:'session-capital'})+field('goal.reserve','Dinero que dejo apartado ($)',s.goal.reserve,{id:'session-reserve'})+'</div><details class="calc-optional"><summary>Escribir mis actividades aquí</summary>'+inlineActivities('session')+'</details></div>');
 document.querySelectorAll('.calc-activity-editor').forEach((node,i)=>{node.insertAdjacentHTML('beforeend','<label class="calc-check"><input type="checkbox" data-b-prep-once="'+i+'" '+(s.activities[i].prepOnce?'checked':'')+'> Preparo una sola vez por partida (si no, en cada misión)</label>');});
 B.tools.forEach(t=>{const panel=$('panel-'+t);panel.insertAdjacentHTML('afterbegin','<div class="b-mode-summary" id="mode-summary-'+t+'"></div>');panel.insertAdjacentHTML('beforeend','<div class="b-expert calc-card calc-subsection" id="expert-'+t+'"></div><div class="b-stage-actions">'+btn('Ver los ajustes avanzados (modo Experto)','data-b-mode="advanced" data-b-advanced="'+t+'"')+'<span class="b-expert-only">'+btn('Esta etapa está lista ✓','data-b-complete="'+t+'"')+'</span>'+btn('Ir a mi plan de negocio','data-open="plan"')+'</div>');});
 /* v7.66 : options retirées en v7.47 rendues au mode Expert : les deux blocs « Mes calculs enregistrés » / « Mes business plans » du bas de page (ils ouvrent le tiroir sur la bonne liste) */
 /* v7.71 : le bloc vit hors de #calc-panels, que mount() vide à chaque restauration (calcul rechargé, lien, Léo) : l'ancien est retiré avant d'écrire le nouveau (il était dupliqué) */
 document.querySelectorAll('.b-legacy-saved').forEach(n=>n.remove());
 $('calc-panels').insertAdjacentHTML('afterend','<div class="b-expert-only b-legacy-saved"><details class="calc-advanced"><summary>Mis cálculos guardados</summary><p class="calc-note">Tus cálculos guardados en este dispositivo, con su ficha.</p>'+btn('Ver mis cálculos guardados','data-b-saved-view="calcs"')+'</details><details class="calc-advanced"><summary>Mis planes de negocio</summary><p class="calc-note">Tus planes guardados en este dispositivo, con su ficha.</p>'+btn('Ver mis planes de negocio','data-b-saved-view="plans"')+'</details></div>');
 $('panel-purchase').querySelector('.calc-card').insertAdjacentHTML('beforeend','<div class="b-purchase-links">'+btn('¿Vale la pena?','data-b-roi-current="1"')+btn('Añadir a “¿Qué compro primero?”','data-b-order-current="1"')+'</div>');
 document.querySelectorAll('.b-expert input[data-number],.calc-advanced input[data-number]').forEach(el=>{const path=el.dataset.field;if(!path)return;let ref=api.initial;for(const k of path.split('.'))ref=ref?.[k];if(path.startsWith('assets.')&&ref===undefined)ref=path.endsWith('extras')||path.endsWith('fees')||path.endsWith('boostHourly')?0:null;if(ref===undefined)return;el.closest('.calc-field').insertAdjacentHTML('beforeend','<small>Valor por defecto: '+esc(ref===null?'sin datos':nf.format(ref))+'</small><button type="button" class="calc-text-button" data-b-default="'+esc(path)+'" data-b-default-value="'+esc(ref===null?'null':ref)+'">Restablecer este valor</button>');});
 mode();
 }
 function mode(){const s=state();$('calc-panels').dataset.mode=s.views[s.tab]||s.mode;document.body.dataset.calcMode=s.views[s.tab]||s.mode;document.querySelectorAll('.calc-mode-switch [data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===s.views[s.tab])));}
 function resultValue(t,r,s=state()){const [key,,unit]=B.metric(t,s);if(!r?.valid||!Number.isFinite(r[key]))return 'Aún no se puede calcular';return unit==='$'?money(r[key]):unit==='h'?hours(r[key]):hours(r[key]/60);}
 function summary(t,s=state()){const r=B.evaluate(t,s,sourceActivities);if(!r.valid)return r.reason;const [key,label]=B.metric(t,s);return label+': '+resultValue(t,r,s);}
 function relevantActivities(t,s){
 const all=B.activities(s,sourceActivities);
 if(t==='goal'&&s.model==='cycles'){if(s.goal.selected!=='mixed')return all.filter(a=>a.id===s.goal.selected);return all.filter(a=>s.activities.some(x=>x.id===a.id)&&a.players<=s.goal.players&&(a.requiresPurchaseIds||[]).every(id=>s.assets.some(x=>x.itemId===id&&x.owned)));}
 if(t==='activities')return all.filter(a=>a.id===s.inverse.selected);
 if(t==='session')return B.eligible(s,sourceActivities);
 if(t==='roi'&&B.roiMode(s)!=='continuous')return all.filter(a=>s.roi.activityIds.includes(a.id));
 return [];
 }
 function effectiveRows(t,s){const g=s.goal,a=B.asset(s,t==='roi'?s.roi.key:s.purchase.key),rows=[];const add=(k,v,u='')=>rows.push([k,typeof v==='number'?nf.format(v)+(u?' '+u:''):v==null?'Desconocido':String(v)+(u?' '+u:'')]);
 if(['goal','session','activities','purchase','order','budget'].includes(t)){add('Ya tengo',g.capital,'$');add('Apartado',g.reserve,'$');}
 if(['goal','session','purchase'].includes(t))add('Quiero tener',g.target,'$');
 if(t==='goal'&&s.model==='continuous'||['purchase','order'].includes(t))add('Gano por hora',g.hourly,'$');
 if(t==='goal'&&s.model==='cycles'||['session','activities'].includes(t)||t==='roi'&&B.roiMode(s)!=='continuous')add('Jugadores',g.players);
 relevantActivities(t,s).forEach(x=>{add(x.name+': recompensa',x.reward,'$');add('Mi parte',x.share,'%');add('Gastos en cada misión',x.cost,'$');add('Duración / preparación / espera',[x.duration,x.prep,x.cooldown].map(v=>v==null?'sin escribir':nf.format(v)).join(' / '),'min');add('Preparación',x.prepOnce?'una vez por partida':'en cada misión');if(t!=='roi'){add('Compra inicial',x.investment,'$');add('Comprar antes',(x.requiresPurchaseIds||[]).map(id=>catalogue.find(c=>c.id===id)?.name||id).join(', ')||'nada');}add('Jugadores necesarios',x.players);});
 if(t==='goal')add('Juego cada día',g.dailyMinutes,'min');if(t==='activities')add('Tiempo que tengo',s.inverse.minutes,'min');
 if(t==='session'){add('Mi partida de esta noche',s.session.minutes,'min');add('Una partida, normalmente',s.session.usualMinutes,'min');add('Días de juego por semana',s.session.daysPerWeek);add('Misma actividad seguida, como máximo',s.session.maxRepeat);}
 if(['roi','purchase'].includes(t)&&a){add('Compra',a.name);add('Mi precio',a.price,'$');add('Precio del sitio',a.referencePrice,'$');add('Opciones y gastos extra',a.extras,'$');add('Otros gastos iniciales',a.fees,'$');}
 if(t==='purchase'&&a){add('¿Esta compra me hace ganar dinero?',({none:'No, es por diversión',personal:'Mi propia cifra',roi:'Desde “¿Vale la pena?”'})[a.incomeMode]);add('Lo que me hace ganar de más, por hora',B.purchase(s,sourceActivities).boostHourly,'$');}
 if(t==='roi'){add('Tengo',g.capital,'$');add('Apartado',g.reserve,'$');add('Tiempo de juego contado',s.roi.hours,'h');add('Lo que cambia la compra',({estimate:'Por gusto, o no lo sé',new:'Actividad nueva',improve:'Actividad mejorada',continuous:'Mi propia cifra'})[B.roiMode(s)]);if(B.roiMode(s)==='continuous'){add('Lo que genera, por hora',s.roi.revenueHourly,'$');add('Lo que cuesta, por hora',s.roi.costHourly,'$');}else if(B.roiMode(s)==='improve'){add('Recompensa extra',s.roi.gainPercent,'%');add('Misión más corta en',s.roi.durationReduction,'%');}}
 if(t==='order')B.orderInput(s,sourceActivities).items.forEach((x,i)=>{add((i+1)+'. '+x.name,x.price,'$');add('Ganado de más por hora, una vez comprado',x.boostHourly,'$');});
 if(t==='budget')B.budgetInput(s).allocations.forEach((v,i)=>add('Gasto '+(i+1),v,'$'));
 return rows;
 }
 const formulas={compare:'Dinero utilizable = lo que tienes − el dinero apartado. “¿Cuándo?” = lo que falta ÷ lo que ganas por hora. Ganas por cada 100.000 $ = tu nota ÷ el precio × 100.000. “Se recupera” = precio ÷ lo que la compra te hace ganar de más, solo si lo has escrito.',goal:'Lo que te falta = lo que quieres − (lo que tienes − el dinero apartado). Si ganas poco a poco: tiempo de juego = lo que te falta ÷ lo que ganas por hora. Si ganas al final de las misiones: solo dan dinero las misiones terminadas. Contamos la compra inicial, los gastos, la preparación y la espera. El número de partidas se redondea hacia arriba.',activities:'Ganancia de una misión = recompensa × tu parte ÷ 100 − los gastos. El número de misiones depende de tu tiempo, de la preparación y de la espera entre dos misiones. Ganado en total = misiones terminadas × ganancia de una misión − la compra inicial, pagada una sola vez.',session:'Se pagan los gastos y la compra inicial antes de cada misión. La recompensa llega al final. Dos misiones nunca se juegan a la vez. Durante una espera, puedes hacer otra misión. Probamos muchos programas y nos quedamos con el mejor que encontramos. Puede que exista uno aún mejor.',purchase:'Te queda = lo que tienes − el dinero apartado − el precio − los gastos. El tiempo para volver a ganar el precio se calcula con lo que ganas por hora. Si no tienes suficiente, te decimos cuánto falta: la compra no se paga.',roi:'Precio inicial = precio + opciones + gastos. Las misiones que van con esta compra se juegan una tras otra: gastos al principio, recompensa al final, con su espera. “Recuperado” = el momento en que lo que ha generado la compra llega a su precio inicial. Para una mejora, comparamos antes y después, en el mismo momento. Con una cifra por hora: precio inicial ÷ (lo que genera − lo que cuesta, por hora).',order:'Para cada compra, en orden: juegas hasta tener suficiente (precio + dinero apartado − lo que tienes), ganando tu cifra por hora. Luego pagas. Si la compra da dinero, solo ganas más después de pagarla. Si no ganas nada por hora y falta dinero, la lista se detiene en esa compra.',budget:'Gastos = los precios y gastos de tus compras (o los gastos que escribas) + tus otros gastos. Te queda = lo que tienes − los gastos − el dinero apartado. Lo que ganes más adelante no cuenta aquí.'};
 function table(rows,caption,comparison=false){return '<div class="calc-table-wrap'+(comparison?' c-comparison':'')+'" '+(comparison?'data-c-comparison="1" ':'')+'tabindex="0" role="region" aria-label="'+esc(caption)+'"><table class="calc-table"><caption>'+esc(caption)+'</caption><tbody>'+rows.map(row=>'<tr>'+row.map((v,i)=>(i?'<td>':'<th scope="row">')+esc(v)+(i?'</td>':'</th>')).join('')+'</tr>').join('')+'</tbody></table></div>';}
 /* v7.66 : « Et si je gagne plus, ou moins ? » (retiré en v7.47, rendu au mode Expert) : le même moteur que Mon objectif
    (B.evaluate), refait avec le gain par heure −20 % et +20 % ; seul ce chiffre change, rien n’est une prévision. */
 function goalEarn(s){if(s.model!=='continuous'||!Number.isFinite(s.goal.hourly))return '<p class="calc-note">Esta prueba cambia lo que ganas por hora: se calcula cuando Mi objetivo cuenta con una ganancia por hora.</p>';
  return '<div class="calc-routes">'+[.8,1,1.2].map(m=>{const c=B.copy(s);c.goal.hourly=s.goal.hourly*m;const v=B.evaluate('goal',c,sourceActivities);return '<article class="calc-route"><span class="calc-tag">'+(m===1?'TU CIFRA':m<1?'20 % MENOS':'20 % MÁS')+'</span><strong>'+(v.valid?hours(v.totalMinutes/60):esc(v.reason||'No se puede calcular'))+'</strong><p>'+money(s.goal.hourly*m)+' por hora</p></article>';}).join('')+'</div><p class="calc-note">Rehacemos el cálculo con un 20 % menos y un 20 % más. No es una previsión.</p>';}
 function expert(t){const s=state(),r=B.evaluate(t,s,sourceActivities),sens=B.sensitivity(t,s,sourceActivities),ref=notebook.reference(t);
 let content='<div class="b-doc-title b-doc-title--plain"><span class="b-doc-num">★</span><div><h3>Modo Experto: todo el detalle</h3><p class="b-doc-lead">Las mismas cifras que en Simple, con todo el detalle. Toca un punto para abrirlo.</p></div></div>';
 if(sens&&sens.pending)content+=fold(t+'-sensitivity',{n:1,title:'¿Y si la cifra cambia un 20 %?',teaser:esc(sens.label+' · aún no se puede calcular'),body:'<p class="calc-note">'+esc(sens.need)+'</p>'});
 else if(sens){const [key,label,unit]=B.metric(t,s),vals=sens.rows.filter(x=>x.result.valid&&Number.isFinite(x.result[key])).map(x=>x.result[key]);content+=fold(t+'-sensitivity',{n:1,title:'¿Y si la cifra cambia un 20 %?',teaser:esc(sens.label+(vals.length?' · de '+resultValue(t,{valid:true,[key]:Math.min(...vals)})+' a '+resultValue(t,{valid:true,[key]:Math.max(...vals)}):'')),body:()=>visual.sensitivity(t,sens,B.metric(t,s),sens.path&&!sens.sourceInput?sens.path.join('.'):null)+'<p class="calc-note">'+esc(sens.label)+'. Solo cambia una cifra; todo lo demás se queda igual. Haz clic en un punto del gráfico para quedarte con esa cifra.</p>'+table(sens.rows.map(x=>[(x.factor===1?'Tu cifra':x.factor<1?'−20 %':'+20 %'),x.value===null?'Valor desconocido':nf.format(x.value)+(x.bounded?' (como máximo 1 billón)':''),x.result.valid?resultValue(t,x.result):x.result.reason]),'Y si · '+B.metric(t,s)[1])});}
 if(t==='goal')content+=fold('goal-earn',{n:1,title:'¿Y si gano más, o menos?',teaser:esc(s.model==='continuous'&&Number.isFinite(s.goal.hourly)?'20 % menos, tu cifra, 20 % más':'solo con una ganancia por hora'),body:()=>goalEarn(s)});
 let compare='<label class="calc-label" for="b-reference-'+t+'">Comparar con un cálculo guardado de '+esc(B.names[t])+'</label><select id="b-reference-'+t+'" data-b-reference="'+t+'">'+opts([['','Nada que comparar'],...notebook.list(t).map(e=>[e.id,e.name+' · '+date(e.updatedAt)])],ref?.id||'')+'</select>'+btn('Guardar para comparar','data-b-keep-ref="'+t+'"');
 if(ref){const old=B.evaluate(t,ref.config,sourceActivities),[key,label,unit,direction]=B.metric(t,s);if(B.metric(t,ref.config)[0]===key&&r.valid&&old.valid&&Number.isFinite(r[key])&&Number.isFinite(old[key])){const delta=r[key]-old[key],percent=old[key]===0?'Sin porcentaje: el cálculo guardado vale 0':Number.isFinite(delta/Math.abs(old[key])*100)?nf.format(delta/Math.abs(old[key])*100)+' %':'Diferencia relativa fuera de rango';compare+=table([[label,resultValue(t,r),resultValue(t,old)],['Diferencia absoluta',(delta>=0?'+':'−')+(unit==='$'?money(Math.abs(delta)):unit==='h'?hours(Math.abs(delta)):hours(Math.abs(delta)/60)),percent]],'Actual / referencia “'+ref.name+'” · '+date(ref.updatedAt),true)+'<p>'+esc(delta===0?'Resultados idénticos en este criterio.':delta*direction>0?'El escenario actual sale mejor en este criterio.':'El cálculo guardado sale mejor aquí.')+'</p>';}else compare+=warning('No se puede comparar: los dos cálculos tienen que responder a la misma pregunta (lo que me queda, o lo que genera la compra).');/* lot 2 (C13) : une référence calculée sous une ancienne version des règles le dit (l’information survit à toute réécriture du carnet) */if(Number.isInteger(ref.config.modelUpgradedFrom))compare+='<p class="calc-note">'+esc('Las reglas de cálculo han cambiado desde este registro (versión {a} → {b}): la referencia se recalcula con las reglas actuales.'.replace('{a}',ref.config.modelUpgradedFrom).replace('{b}',B.MODEL_VERSION))+'</p>';if(ref.dataVersion!==s.dataVersion)compare+='<p class="calc-note">La versión de los datos ha cambiado; la referencia se recalcula con el catálogo actual.</p>';}
 content+=fold(t+'-reference',{n:2,title:'Comparar con un cálculo guardado',teaser:esc(ref?'Referencia: '+ref.name:(notebook.list(t).length?notebook.list(t).length+' cálculo(s) guardado(s) para comparar':'Guarda un cálculo para compararlo')),body:compare});
 const rawLabels={missing:'Cantidad por ganar ($)',availableCapital:'Dinero utilizable ($)',reserve:'Apartado ($)',hourly:'Ganancia por hora ($)',totalMinutes:'Tiempo total (min)',hours:'Tiempo (h)',activeMinutes:'Tiempo en misión (min)',waitMinutes:'Espera (min)',unusedMinutes:'Tiempo que queda (min)',sessions:'Partidas necesarias',days:'Días, con una partida por día',finalCapital:'Tendrás al final ($)',runs:'Misiones terminadas',investment:'Compra inicial ($)',continuousMinutes:'Tiempo jugando sin parar (min)',profit:'Ganado durante la partida ($)',netHourly:'Ganancia por hora ($)',grossProfit:'Generado durante este tiempo ($)',operatingProfit:'Generado, con los gastos pagados ($)',netProfit:'Ganado al final, descontado el precio ($)',roiPercent:'Ganado al final, en % del precio',paybackHours:'Recuperado tras (horas de juego)',paybackCycles:'Misiones hasta recuperarlo',costs:'Lo que cuesta durante este tiempo ($)',beforeNet:'Ganancia antes de la mejora ($)',afterNet:'Ganancia después de la mejora ($)',searchedMinutes:'Tiempo revisado (min)',remaining:'Te quedará ($)',capitalPercent:'Parte de mi dinero (%)',recoveryHours:'Tiempo para volver a ganar el precio (h)',goalDelayHours:'Retraso en el objetivo (h)',shortfall:'Cantidad que falta ($)',totalHours:'Tiempo hasta la última compra (h)',finalHourly:'Luego ganas ($ por hora)',spent:'Gastos ($)',available:'Te queda ($)',cashRemaining:'Te queda ($)',waitHours:'Tiempo hasta tener suficiente (h)',buyNowCash:'Si compras ahora ($)',waitCash:'Si esperas ($)'};
 const resultRows=Object.entries(r).filter(([key,v])=>rawLabels[key]&&(typeof v==='number'||v===null)).map(([key,v])=>[rawLabels[key],v===null?'Aún no se puede calcular':nf.format(v)]);
 content+=fold(t+'-formula',{n:3,title:'¿Cómo se calcula?',teaser:esc(formulas[t].split('.')[0]+'.'),body:()=>'<p>'+esc(formulas[t])+'</p>'+table(effectiveRows(t,s),'Las cifras usadas')+'<p class="calc-note">Los tiempos se redondean al minuto superior. Los nombres, las imágenes y los precios del sitio vienen de nuestras fichas. Las demás cifras son tuyas. Una cifra que no conocemos se queda vacía. Nunca usamos las cifras de GTA Online.</p>'});
 content+=fold(t+'-raw',{n:4,title:'Todas las cifras del cálculo',teaser:esc(resultRows.length+' cifras'),body:()=>table(resultRows,'Todas las cifras del cálculo')});
 return '<div class="b-doc b-doc--light">'+content+'</div>';
 }
 function date(v){return Number.isFinite(Date.parse(v))?new Date(v).toLocaleString('es-ES',{dateStyle:'short',timeStyle:'short'}):v;}
