    const cols=[['','Sin la compra','Con la compra'],['Pago al principio',money(0),money(r.investment)],['Lo que genera en '+hours(H)+', quitando los gastos de las misiones',known&&!improve?money(r.opportunityCost):improve?money(r.beforeNet):'—',known&&!improve?money(r.operatingProfit):improve?money(r.afterNet):money(r.operatingProfit)],['Diferencia, quitando el precio','',money(net)]];
