  const envie=v=>v===null||v===undefined?'sin puntuar':v+' / 5',unknownNames=r.items.filter(it=>!it.known).map(it=>it.name),partialNote=unknownNames.length?' <i>'+esc(unknownNames.map(n=>'“'+n+'”').join(', '))+(lkPluriel(unknownNames.length)?' no tienen precio: la respuesta solo vale para los precios conocidos. Escribe los que imaginas, pueden cambiar la elección.':' no tiene precio: la respuesta solo vale para los precios conocidos. Escribe el que imaginas, puede cambiar la elección.')+'</i>':'';
  if(r.undecided)html+='<p class="b-answer calc-answer">Aún no puedo decidir: '+esc(r.undecidedReason)+'</p>';
  else if(!best)html+='<p class="b-answer calc-answer">No puedo desempatar: '+esc(r.criterion==='profit'?'ninguna de estas compras da dinero según tus cifras.':r.criterion==='utility'&&r.unrated&&r.unrated.length?'puntúa tus ganas (de 1 a 5) para '+r.unrated.map(n=>'“'+n+'”').join(', ')+'.':'faltan cifras.')+'</p>';
  else{html+='<p class="b-answer calc-answer" data-short="'+esc(best.name)+'">'+(r.tie?'Empate: <b>'+esc(best.name)+'</b> y <b>'+esc(r.closeWith)+'</b> cuestan lo mismo en '+sessions+' partidas. Desempata con tus ganas.':'Para ti, es <b>'+esc(best.name)+'</b>: '+esc(crit)+'.'+(r.near?' Resultado parecido a “'+esc(r.closeWith)+'” (menos de un 2 % de diferencia): tus ganas pueden desempatar.':'')+tieNote(r.criterion))+' Puedes comprarlo '+esc(when(best))+'.'+partialNote+(r.fallback?' <i>Sin tu nota de ganas para '+esc(r.fallback.unrated.map(n=>'“'+n+'”').join(', '))+', la relación ganas / precio no puede decidir: puntúa tus ganas (de 1 a 5) para obtenerla.</i>':'')+(cond?' <i>Siempre que se confirme en el juego: '+esc(row(best.name).admission.assumed.concat(row(best.name).admission.unknown).map(c=>c.label).join(', '))+'.</i>':'')+'</p>'+stats([['Precio total',money(best.total)],r.criterion==='cheapestTotal'&&r.totals?['Coste en '+sessions+' partidas',money(r.totals[best.name])]:['Te queda después',best.affordable?money(r.available-best.total):'No llega'],['Tus ganas',envie(best.utility)]]);
   html+='<div class="calc-next-action"><strong>Tu próximo paso</strong><p>'+esc(best.affordable?'Compra “'+best.name+'” ahora: te quedarán '+money(r.available-best.total)+' sin contar el dinero apartado. Si dudas, mira “Según lo que importa”: otro criterio puede cambiar la elección.':best.waitHours!==null?'Sigue jugando '+hours(best.waitHours)+' antes de poder pagar “'+best.name+'”, o elige una compra que puedas tener ahora ('+(r.bestByCriterion.fastest||'ninguna')+').':'Escribe lo que ganas por hora para saber cuándo podrás pagarte “'+best.name+'”.')+'</p>'+btn('Hacerlo el objetivo de mi plan de negocio','data-b-compare-to-plan="'+esc(s.compare.keys.find(k=>B.compareNames(s)[k]===best.name)||'')+'"'/* lot 3 : par le nom unique du comparateur (deux achats du même nom ne se confondent plus) */)+'</div>';}
  html+=excludedHTML;
