  html+='<h4>Según lo que importa</h4><ul class="b-compare-picks">'+[['value','Relación ganas / precio'],['cheapest','El más barato de comprar'],['cheapestTotal','El más barato con el tiempo'],['fastest','El que antes puedes tener'],['profit','Se recupera antes'],['utility','Más ganas']].map(([k,l])=>{const name=(k==='cheapestTotal'?(r.criterion==='cheapestTotal'?r.best:null):r.bestByCriterion[k])||'—',with_=k==='cheapestTotal'?(r.criterion==='cheapestTotal'&&r.tie?[r.closeWith]:[]):tiedWith(k);return '<li><span>'+l+'</span><b>'+esc(name)+'</b>'+(with_.length?'<small class="b-compare-tie">empatado con '+with_.map(n=>'“'+esc(n)+'”').join(', ')+'</small>':'')+'</li>';}).join('')+'</ul>';
