  html+='<div class="c-detail">'+table([['',...r.items.map(it=>it.name)],['Precio total',...r.items.map(it=>it.known?money(it.total):'por escribir')],['Coste de uso',...r.items.map(it=>U(it.name))],['Coste en '+(sessions?sessions+' partidas':'el tiempo (horas de uso por escribir, modo Experto)'),...r.items.map(it=>T(it.name))],['Encaja con lo que necesitas',...r.items.map(it=>N(it.name))],['¿Puedo comprarlo?',...r.items.map(it=>!it.known?'—':it.affordable?'Sí':'Te faltan '+money(it.shortfall))],['¿Cuándo?',...r.items.map(it=>it.known?when(it):'—')],['Ganas',...r.items.map(it=>it.known?envie(it.utility):'—')],['Ganas por 100.000 $',...r.items.map(it=>it.valueScore===null?'—':nf.format(Math.round(it.valueScore*100)/100))],['Tiempo para volver a ganar el precio',...r.items.map(it=>it.recoveryHours===null||it.recoveryHours===undefined?'—':hours(it.recoveryHours))],['¿Da dinero?',...r.items.map(it=>it.paybackHours===null?'No (o sin escribir)':'Recuperado tras '+hours(it.paybackHours))],/* v7.59 (check ultime, D-04) : « Je m’en sers pendant (heures de jeu) » (compare.hours) ne changeait rien à l’écran ; ce qu’il laisse après ce temps, prix enlevé, est maintenant montré pour les achats qui rapportent. */['Tras '+hours(s.compare.hours)+' de juego, descontando el precio',...r.items.map(it=>it.gainOverHorizon===null||it.gainOverHorizon===undefined?'—':(it.gainOverHorizon>=0?'+':'−')+money(Math.abs(it.gainOverHorizon)))]],'Todas las compras lado a lado · mismas cifras iniciales',true)+'</div>';
