  if(t==='session')return [['Tiempo para jugar',hours(s.session.minutes/60)],['Actividades marcadas',nf.format(s.session.enabled.length)],['Tengo',cash(g.capital)]];
  if(t==='activities')return [['Actividad',activityName(s,s.inverse.selected)],['Tiempo para jugar',hours(s.inverse.minutes/60)],['Tengo',cash(g.capital)]];
