  if(el.dataset.bRoiActivity){s.roi.activityIds=el.checked?[...new Set([...s.roi.activityIds,el.dataset.bRoiActivity])]:s.roi.activityIds.filter(x=>x!==el.dataset.bRoiActivity);afterEdit();return true;}
