  if(el.dataset.field==='roi.mode'||el.dataset.field==='roi.recoveryActivity'||el.dataset.field==='compare.criterion'){api.setPath(el.dataset.field,el.value);/* v7.66 : choisir un mode à gain pour un achat déclaré « plaisir » ou « confort » change aussi son rôle (sinon le choix resterait sans effet) */if(el.dataset.field==='roi.mode'&&el.value!=='estimate'){const ra=lookup(s.roi.key);if(ra&&(ra.role==='pleasure'||ra.role==='comfort'))ra.role={new:'unlock',improve:'improve',continuous:'income'}[el.value]||'unknown';}refresh(el.id);return true;}
