  if(d.cApply!==undefined){const [path,raw]=d.cApply.split('|'),value=Number(raw);if(path&&Number.isFinite(value)){api.setPath(path,value);document.querySelectorAll('[data-field="'+path+'"]').forEach(i=>{i.value=value;});afterEdit();api.notify('Cifra aplicada: '+nf.format(value)+'.');}return true;}
