  if(d.bDuplicate){try{notebook.duplicate(d.bDuplicate);renderSaved();}catch(e){api.notify(e.message);}return true;}if(d.bDelete){const gone=notebook.get(d.bDelete)?.name||'';notebook.remove(d.bDelete);renderSaved();document.querySelector('#'+(drawerView==='plans'?'saved-plans-list':'saved-list')+' [data-b-notebook-undo]')?.focus();api.notify('“'+gone+'” se ha eliminado. Puedes deshacerlo.');return true;}if(d.bNotebookUndo){try{notebook.undo();renderSaved();}catch(e){api.notify(e.message);}return true;}
  /* v7.66 : options rendues au mode Expert */
  if(d.bAdvanced){const t=d.bAdvanced;requestAnimationFrame(()=>{const st=state();if((st.views[t]||st.mode)!=='advanced')return;const box=$('expert-'+t);if(!box)return;box.querySelectorAll('[data-fold]').forEach(f=>foldSet(f.dataset.fold,true));box.innerHTML=expert(t);box.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});const h=box.querySelector('h3');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}});return false;}
  if(d.bComplete){const t=d.bComplete,r=B.evaluate(t,s,sourceActivities);if(!r.valid){api.notify(r.reason||'Falta una cifra para responder.');return true;}if(!s.completed.includes(t))s.completed.push(t);api.saveLocal();const res=$('panel-'+t)?.querySelector('.calc-result');if(res){res.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});res.focus({preventScroll:true});}api.notify('Etapa validada: '+B.names[t]+'.');return true;}
  if(d.bKeepRef){const t=d.bKeepRef;try{const name=(s.name&&s.name!==api.initial.name?s.name:B.names[t])+' · '+date(new Date().toISOString()),r=notebook.save(t,s,name,B.names[t]+' · '+summary(t),true);notebook.setReference(t,r.entry.id);renderSaved();$('expert-'+t).innerHTML=expert(t);api.notify('Guardado para comparar: “'+r.entry.name+' ». Change un chiffre : la comparaison se met à jour.');}catch(e){api.notify(e.message);}return true;}
  if(d.bRefEntry){const e=notebook.get(d.bRefEntry);if(e){notebook.setReference(e.tool,e.id);closeDrawer();s.views[e.tool]='advanced';s.mode='advanced';api.openTab(e.tool);render();api.saveLocal();api.notify('“'+e.name+'” es ahora la referencia para comparar.');}return true;}
  if(d.bSavedView){openDrawer(d.bSavedView);return true;}
  if(d.bPrint){$('calc-print')?.click();return true;}
  if(d.calcResetProxy!==undefined){closeDrawer();$('calc-reset')?.click();return true;}
  if(d.calcZeroProxy!==undefined){closeDrawer();document.querySelector('.calc-data-note [data-calc-zero]')?.click();return true;}
  if(d.bFocus){const target=$(d.bFocus);if(target?.closest('.b-expert')){s.views[s.tab]='advanced';s.mode='advanced';mode();api.saveLocal();}target?.focus();return true;}
  if(d.bDefault){const value=d.bDefaultValue==='null'?null:Number(d.bDefaultValue);api.setPath(d.bDefault,value);document.querySelectorAll('[data-field="'+d.bDefault+'"]').forEach(x=>x.value=value??'');afterEdit();return true;}
  if(d.bPriceReset){const a=lookup(d.bPriceReset),item=itemFor(a);a.price=item?item.price:null;a.referencePrice=item?item.price:null;refresh(s.tab==='roi'?'f-roi-purchase':s.tab==='purchase'?'f-purchase-price':null);return true;}
  if(d.bRoiCurrent){s.roi.key=s.purchase.key;const item=itemFor(lookup(s.roi.key));s.roi.activityIds=B.activities(s,sourceActivities).filter(x=>item?.activityIds.includes(x.id)||x.purchaseIds?.includes(item?.id)).map(x=>x.id);s.tab='roi';refresh('f-roi-purchase');return true;}
  if(d.bRoi){const item=catalogue.find(x=>x.id===d.bRoi);if(item?.purchaseCandidate){let a;try{a=B.addAsset(s,item);}catch(e){api.notify(e.message);return true;}s.roi.key=a.key;s.purchase.key=a.key;s.tab='roi';s.roi.activityIds=B.activities(s,sourceActivities).filter(x=>item.activityIds.includes(x.id)||x.purchaseIds?.includes(item.id)).map(x=>x.id);refresh('f-roi-purchase');}return true;}
  if(d.bOrderCurrent||d.bOrderRoi||d.bOrderRoiIncome){const key=d.bOrderCurrent?s.purchase.key:s.roi.key;if(!s.order.keys.includes(key))s.order.keys.push(key);if(d.bOrderRoiIncome)lookup(key).incomeMode='roi';orderEditor=key;s.tab='order';refresh('order-search');return true;}
  if(d.bRoiManual||d.bRoiAlternative){if(s.assets.length>=40){api.notify('Cuarenta compras como máximo.');return true;}const key='free-'+Date.now().toString(36)+'-'+s.assets.length;s.assets.push({key,itemId:'',name:d.bRoiAlternative?'Mi otra compra':'Mi compra libre',price:null,referencePrice:null,extras:0,fees:0,owned:false,incomeMode:'none',boostHourly:0});if(d.bRoiAlternative)s.roi.compareKey=key;else{s.roi.key=key;s.purchase.key=key;s.roi.activityIds=[];s.roi.mode='estimate';}refresh(d.bRoiAlternative?'roi-alternative-price':'f-roi-purchase');return true;}
