  if(d.bCompareFree){if(s.assets.length>=40){api.notify('Cuarenta compras como máximo.');return true;}const key='free-'+Date.now().toString(36)+'-'+s.assets.length;s.assets.push({key,itemId:'',name:'Mi compra libre',price:null,referencePrice:null,extras:0,fees:0,owned:false,incomeMode:'none',boostHourly:0,utility:3});s.compare.keys.push(key);refresh('compare-price-'+(s.compare.keys.length-1));return true;}
  if(d.bCompareRemove){s.compare.keys=s.compare.keys.filter(k=>k!==d.bCompareRemove);refresh('compare-search');return true;}
