 document.addEventListener('keydown',ev=>{const pt=ev.target.closest&&ev.target.closest('.c-chart-point.is-actionable');if(pt&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();pt.dispatchEvent(new global.Event('click',{bubbles:true}));return;}const el=ev.target;if(!el.dataset||!el.dataset.bCombo)return;if(ev.key==='Escape'){closeCombo();ev.preventDefault();return;}if(['ArrowDown','ArrowUp'].includes(ev.key)){ev.preventDefault();if(combo!==el||el.getAttribute('aria-expanded')!=='true')search(el);if(!comboRows.length)return;comboIndex=(comboIndex+(ev.key==='ArrowDown'?1:-1)+comboRows.length)%comboRows.length;const id=el.id+'-option-'+comboIndex;el.setAttribute('aria-activedescendant',id);document.querySelectorAll('#'+el.id+'-list [role="option"]').forEach((n,i)=>n.setAttribute('aria-selected',String(i===comboIndex)));const list=$(el.id+'-list'),row=$(id),lr=list.getBoundingClientRect(),rr=row.getBoundingClientRect();if(rr.top<lr.top)list.scrollTop-=lr.top-rr.top;else if(rr.bottom>lr.bottom)list.scrollTop+=rr.bottom-lr.bottom;}else if(ev.key==='Enter'&&comboIndex>=0){ev.preventDefault();selectSuggestion(comboIndex);}});
